  1→import express, { Request, Response } from "express";
  2→import { query, AgentDefinition } from "@anthropic-ai/claude-agent-sdk";
  3→import { Langfuse } from "langfuse";
  4→import { mkdirSync, writeFileSync, existsSync } from "fs";
  5→import { homedir } from "os";
  6→import { join } from "path";
  7→import type { QueryRequest, HealthResponse, AgentDefinitionPayload } from "./types.js";
  8→
  9→// Claude CLI requires certain directories/files under ~/.claude to exist.
 10→// The container uses a tmpfs mount at ~/.claude which starts empty, so we
 11→// create the expected structure at startup.
 12→const claudeDir = join(homedir(), ".claude");
 13→for (const sub of ["debug", "projects"]) {
 14→  const dir = join(claudeDir, sub);
 15→  if (!existsSync(dir)) {
 16→    mkdirSync(dir, { recursive: true });
 17→  }
 18→}
 19→const settingsFile = join(claudeDir, "remote-settings.json");
 20→if (!existsSync(settingsFile)) {
 21→  writeFileSync(settingsFile, "{}");
 22→}
 23→
 24→// Initialize Langfuse if credentials are available (reads from env vars
 25→// LANGFUSE_PUBLIC_KEY, LANGFUSE_SECRET_KEY, LANGFUSE_BASE_URL automatically)
 26→let langfuse: Langfuse | null = null;
 27→if (process.env.LANGFUSE_PUBLIC_KEY && process.env.LANGFUSE_SECRET_KEY) {
 28→  langfuse = new Langfuse();
 29→  console.log("[sidecar] Langfuse tracing enabled");
 30→}
 31→
 32→const app = express();
 33→app.use(express.json({ limit: "10mb" }));
 34→
 35→const PORT = parseInt(process.env.PORT || "3000", 10);
 36→
 37→// Per-request abort tracking — avoids a global variable whose cleanup in one
 38→// request's `finally` block can clobber a concurrently-started request.
 39→let nextRequestId = 0;
 40→const activeAborts = new Map<number, AbortController>();
 41→
 42→// How long (ms) to wait for the SDK iterator to yield a message before
 43→// aborting.  Resets on every message so active multi-turn queries are not
 44→// interrupted.  Covers cases where the CLI subprocess hangs on startup
 45→// (e.g. broken session resume, unreachable MCP server).
 46→const SDK_IDLE_TIMEOUT_MS = 60_000; // 1 minute
 47→
 48→// Timeout (ms) for pre-flight reachability checks against MCP / API URLs.
 49→const PREFLIGHT_TIMEOUT_MS = 10_000; // 10 seconds
 50→
 51→app.get("/health", (_req: Request, res: Response) => {
 52→  const response: HealthResponse = { status: "ok" };
 53→  res.json(response);
 54→});
 55→
 56→app.post("/query", async (req: Request, res: Response) => {
 57→  const body = req.body as QueryRequest;
 58→
 59→  if (!body.message || !body.system_prompt) {
 60→    res.status(400).json({ error: "message and system_prompt are required" });
 61→    return;
 62→  }
 63→
 64→  // Set up SSE headers
 65→  res.setHeader("Content-Type", "text/event-stream");
 66→  res.setHeader("Cache-Control", "no-cache");
 67→  res.setHeader("Connection", "keep-alive");
 68→  res.setHeader("X-Accel-Buffering", "no");
 69→  res.flushHeaders();
 70→
 71→  const abortController = new AbortController();
 72→  const requestId = nextRequestId++;
 73→  activeAborts.set(requestId, abortController);
 74→
 75→  // Merge per-request env overrides (e.g. Bifrost gateway URLs) with process env
 76→  const sdkEnv: Record<string, string> = {};
 77→  for (const [k, v] of Object.entries(process.env)) {
 78→    if (v !== undefined) sdkEnv[k] = v;
 79→  }
 80→  if (body.env) {
 81→    Object.assign(sdkEnv, body.env);
 82→  }
 83→  // Scrub Langfuse credentials so the agent subprocess cannot read them from
 84→  // the inherited environment — matches backend subprocess behaviour.
 85→  // The sidecar's own Langfuse client already holds the credentials internally.
 86→  sdkEnv["LANGFUSE_PUBLIC_KEY"] = "";
 87→  sdkEnv["LANGFUSE_SECRET_KEY"] = "";
 88→
 89→  let responseEnded = false;
 90→
 91→  // Detect client disconnect
 92→  res.on("close", () => {
 93→    if (!responseEnded) {
 94→      abortController.abort();
 95→    }
 96→  });
 97→
 98→  // --- Langfuse tracing setup ---
 99→  // Mirror the backend's session ID handling:
100→  //   - langfuse_session_id (from frontend for edit/delete) takes priority
101→  //   - session_id (CLI session from previous turn) as fallback
102→  const modelName = body.model || process.env.ORCHESTRATOR_MODEL || "claude-sonnet-4-6";
103→  const traceMessage = body.original_message || body.message;
104→  const traceInput: Record<string, unknown> = {
105→    message: traceMessage.substring(0, 500),
106→  };
107→  if (body.conversation_history && body.conversation_history.length > 0) {
108→    traceInput.conversation_history = body.conversation_history;
109→  }
110→  const trace = langfuse?.trace({
111→    name: "agent-chat",
112→    sessionId: body.langfuse_session_id || body.session_id || undefined,
113→    input: traceInput,
114→    metadata: { model: modelName, mode: "container" },
115→  });
116→
117→  // Per-turn usage tracking from stream events
118→  let currentGenUsage: { input?: number; output?: number } = {};
119→  // Accumulated messages for generation input context
120→  const accumulatedMessages: Array<{ role: string; content: unknown }> = [
121→    { role: "user", content: body.message },
122→  ];
123→
124→  // Collect stderr from the CLI subprocess for debugging
125→  const stderrLines: string[] = [];
126→
127→  // Declared here so `finally` can clear it even if `try` throws early
128→  let idleTimer: ReturnType<typeof setTimeout> | null = null;
129→
130→  try {
131→    // --- Pre-flight reachability checks ---
132→    // The CLI subprocess will hang silently if it can't reach the MCP SSE
133→    // server or the Bifrost LLM gateway.  Test connectivity first so we can
134→    // fail fast with a useful error message.
135→    const apiBase = sdkEnv["ANTHROPIC_BASE_URL"] || "";
136→    console.log(
137→      `[sidecar] reqId=${requestId} mcp_url=${body.mcp_server_url || "(none)"} api_base=${apiBase} session_id=${body.session_id || "(none)"}`
138→    );
139→
140→    if (body.mcp_server_url) {
141→      try {
142→        const mcpResp = await fetch(body.mcp_server_url, {
143→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
144→        });
145→        // SSE endpoints normally return 200 with text/event-stream; any
146→        // non-error status is fine — we just need to know the host is up.
147→        mcpResp.body?.cancel(); // don't consume the stream
148→        console.log(`[sidecar] MCP reachability OK (status=${mcpResp.status})`);
149→      } catch (e: unknown) {
150→        const reason = e instanceof Error ? e.message : String(e);
151→        throw new Error(
152→          `MCP server unreachable at ${body.mcp_server_url}: ${reason}. ` +
153→          `Check that BACKEND_BASE_URL is reachable from inside the container.`
154→        );
155→      }
156→    }
157→
158→    if (apiBase) {
159→      try {
160→        // Just a quick TCP-level check — Bifrost will return 4xx without
161→        // a real API key but that still proves reachability.
162→        const apiResp = await fetch(`${apiBase}/v1/models`, {
163→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
164→        });
165→        apiResp.body?.cancel();
166→        console.log(`[sidecar] Bifrost LLM gateway reachability OK (status=${apiResp.status})`);
167→      } catch (e: unknown) {
168→        const reason = e instanceof Error ? e.message : String(e);
169→        throw new Error(
170→          `Bifrost LLM gateway unreachable at ${apiBase}: ${reason}. ` +
171→          `Check that BIFROST_BASE_URL is reachable from inside the container.`
172→        );
173→      }
174→    }
175→
176→    // Convert agents payload from the backend into SDK AgentDefinition objects.
177→    // The SDK only accepts 'sonnet' | 'opus' | 'haiku' | 'inherit' for model.
178→    // Arbitrary strings (e.g. "openai/gpt-5.2") are silently rejected, causing
179→    // the agent to not be registered.  Validate and fall back to "inherit".
180→    const VALID_AGENT_MODELS = new Set(["sonnet", "opus", "haiku", "inherit"]);
181→    let sdkAgents: Record<string, AgentDefinition> | undefined;
182→    if (body.agents) {
183→      sdkAgents = {};
184→      for (const [name, def] of Object.entries(body.agents)) {
185→        const model = def.model && VALID_AGENT_MODELS.has(def.model)
186→          ? (def.model as AgentDefinition["model"])
187→          : "inherit";
188→        sdkAgents[name] = {
189→          description: def.description,
190→          prompt: def.prompt,
191→          ...(def.tools ? { tools: def.tools } : {}),
192→          model,
193→        };
194→      }
195→    }
196→
197→    const sdkQuery = query({
198→      prompt: body.message,
199→      options: {
200→        model: modelName,
201→        systemPrompt: body.system_prompt,
202→        allowedTools: ["Task", "mcp__duckdb__execute_sql"],
203→        permissionMode: "bypassPermissions",
204→        allowDangerouslySkipPermissions: true,
205→        maxTurns: 20,
206→        includePartialMessages: true,
207→        abortController,
208→        env: sdkEnv,
209→        stderr: (line: string) => {
210→          stderrLines.push(line);
211→          console.error(`[sidecar:cli] ${line}`);
212→        },
213→        ...(sdkAgents ? { agents: sdkAgents } : {}),
214→        ...(body.mcp_server_url
215→          ? {
216→              mcpServers: {
217→                duckdb: {
218→                  type: "sse" as const,
219→                  url: body.mcp_server_url,
220→                },
221→              },
222→            }
223→          : {}),
224→        ...(body.session_id ? { resume: body.session_id } : {}),
225→      },
226→    });
227→
228→    console.log(
229→      `[sidecar] SDK query started model=${modelName} reqId=${requestId}`
230→    );
231→
232→    // Idle-timeout: abort if no message arrives within SDK_IDLE_TIMEOUT_MS.
233→    // The timer resets on every message so long-running multi-turn queries
234→    // that are making progress are not interrupted.
235→    idleTimer = setTimeout(() => {
236→      console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
237→      abortController.abort();
238→    }, SDK_IDLE_TIMEOUT_MS);
239→
240→    for await (const message of sdkQuery) {
241→      // Reset idle timer on every message
242→      if (idleTimer) { clearTimeout(idleTimer); }
243→      idleTimer = setTimeout(() => {
244→        console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
245→        abortController.abort();
246→      }, SDK_IDLE_TIMEOUT_MS);
247→
248→      if (responseEnded) break;
249→      // Forward each SDK message as an SSE data line
250→      res.write(`data: ${JSON.stringify(message)}\n\n`);
251→
252→      // --- Create Langfuse observations from SDK messages ---
253→      if (!trace) continue;
254→      const msg = message as Record<string, unknown>;
255→
256→      if (msg.type === "stream_event") {
257→        // Capture per-turn token usage from API stream events
258→        const event = (msg.event as Record<string, unknown>) || {};
259→        const eventType = event.type as string;
260→        if (eventType === "message_start") {
261→          const msgData = (event.message as Record<string, unknown>) || {};
262→          const usage = (msgData.usage as Record<string, number>) || {};
263→          currentGenUsage = { input: usage.input_tokens || 0 };
264→        } else if (eventType === "message_delta") {
265→          const usage = (event.usage as Record<string, number>) || {};
266→          currentGenUsage.output = usage.output_tokens || 0;
267→        }
268→      } else if (msg.type === "assistant") {
269→        // Create a generation observation for each assistant turn
270→        const msgObj = (msg.message as Record<string, unknown>) || {};
271→        const content = msgObj.content as unknown[];
272→
273→        const usage =
274→          currentGenUsage.input !== undefined
275→            ? {
276→                input: currentGenUsage.input || 0,
277→                output: currentGenUsage.output || 0,
278→                total:
279→                  (currentGenUsage.input || 0) +
280→                  (currentGenUsage.output || 0),
281→                unit: "TOKENS" as const,
282→              }
283→            : undefined;
284→
285→        const gen = trace.generation({
286→          name: "claude.assistant.turn",
287→          model: (msgObj.model as string) || modelName,
288→          input: { messages: accumulatedMessages.slice(-6) },
289→          output: { content, role: "assistant" },
290→          usage,
291→        });
292→        gen.end();
293→        currentGenUsage = {};
294→
295→        // Accumulate for next turn's input context
296→        accumulatedMessages.push({ role: "assistant", content });
297→      } else if (msg.type === "user") {
298→        // Accumulate tool results for next turn's input context
299→        const msgObj = (msg.message as Record<string, unknown>) || {};
300→        accumulatedMessages.push({
301→          role: "user",
302→          content: msgObj.content,
303→        });
304→      } else if (msg.type === "result") {
305→        // Finalize trace — mirrors backend's finally block:
306→        //   trace_session_id = langfuse_session_id or actual_session_id
307→        const actualSessionId = (msg.session_id as string | undefined) || body.session_id;
308→        const traceSessionId = body.langfuse_session_id || actualSessionId;
309→        trace.update({
310→          ...(traceSessionId ? { sessionId: traceSessionId } : {}),
311→          output: { session_id: actualSessionId },
312→        });
313→      } else if (msg.type === "system") {
314→        // Capture session_id early — only when no langfuse_session_id override
315→        // (matches backend's propagate_attributes(session_id=langfuse_session_id or session_id))
316→        const sessionId = msg.session_id as string | undefined;
317→        if (sessionId && !body.langfuse_session_id) {
318→          trace.update({ sessionId });
319→        }
320→      }
321→    }
322→  } catch (err: unknown) {
323→    let errMsg = err instanceof Error ? err.message : String(err);
324→    // Append CLI stderr for context when the process crashes
325→    if (stderrLines.length > 0) {
326→      errMsg += ` | CLI stderr: ${stderrLines.slice(-5).join(" ")}`;
327→    }
328→    // Don't log abort errors — they are expected on client disconnect
329→    if (!(err instanceof Error && err.name === "AbortError")) {
330→      console.error(`[sidecar] SDK error: ${errMsg}`);
331→      if (!responseEnded) {
332→        res.write(
333→          `data: ${JSON.stringify({ type: "error", message: errMsg })}\n\n`
334→        );
335→      }
336→      if (trace) {
337→        trace.update({ output: { error: errMsg } });
338→      }
339→    }
340→  } finally {
341→    if (idleTimer) { clearTimeout(idleTimer); }
342→    activeAborts.delete(requestId);
343→    responseEnded = true;
344→    res.end();
345→    // Flush Langfuse events before the response is fully closed
346→    if (langfuse) {
347→      await langfuse.flushAsync().catch(() => {});
348→    }
349→    console.log(`[sidecar] SSE stream ended reqId=${requestId}`);
350→  }
351→});
352→
353→app.post("/stop", (_req: Request, res: Response) => {
354→  if (activeAborts.size > 0) {
355→    for (const [id, controller] of activeAborts) {
356→      controller.abort();
357→      activeAborts.delete(id);
358→    }
359→    res.json({ status: "stopped" });
360→  } else {
361→    res.json({ status: "no_active_session" });
362→  }
363→});
364→
365→app.listen(PORT, "0.0.0.0", () => {
366→  console.log(`Sidecar agent server listening on port ${PORT}`);
367→});
368→

 1→export interface AgentDefinitionPayload {
 2→  description: string;
 3→  prompt: string;
 4→  tools?: string[];
 5→  model?: string;
 6→}
 7→
 8→export interface QueryRequest {
 9→  message: string;
10→  session_id?: string;
11→  system_prompt: string;
12→  model?: string;
13→  mcp_server_url?: string;
14→  env?: Record<string, string>;
15→  agents?: Record<string, AgentDefinitionPayload>;
16→  langfuse_session_id?: string;
17→  original_message?: string;
18→  conversation_history?: Array<{ role: string; content: string }>;
19→}
20→
21→export interface HealthResponse {
22→  status: "ok" | "error";
23→  message?: string;
24→}
25→

  1→import { useState, useRef, useEffect } from 'react';
  2→import ReactMarkdown from 'react-markdown';
  3→import remarkGfm from 'remark-gfm';
  4→import { useTranslation } from '../hooks/useTranslation';
  5→import type { ChatMessage, ContentSegment } from '../types';
  6→import { useAgent } from '../hooks/useAgent';
  7→import { InlineQueryResult } from './InlineQueryResult';
  8→import { ChartWidget } from './ChartWidget';
  9→import { UserQuestion } from './UserQuestion';
 10→import './MessageBubble.css';
 11→
 12→/**
 13→ * Strip chart_spec JSON code blocks from answer text.
 14→ * The orchestrator may include the raw chart spec JSON even though the chart
 15→ * is rendered separately. Remove ```json ... ``` blocks containing chart_spec
 16→ * or Plotly trace data so they don't appear as raw text.
 17→ */
 18→function stripChartSpecBlocks(text: string): string {
 19→  return text.replace(/```(?:json)?\s*\n?\s*\{[\s\S]*?"(?:chart_spec|data)"[\s\S]*?\}\s*\n?\s*```/g, '').trim();
 20→}
 21→
 22→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
 23→  // Use streaming remainder if available
 24→  if (streamingRemainder?.trim()) {
 25→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
 26→    const last = lines[lines.length - 1] || '';
 27→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
 28→  }
 29→  // Otherwise use last thinking segment's last line
 30→  for (let i = segments.length - 1; i >= 0; i--) {
 31→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
 32→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
 33→      const last = lines[lines.length - 1] || '';
 34→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
 35→    }
 36→  }
 37→  return t('thinking');
 38→}
 39→
 40→function ThinkingBlock({ segments, streamingRemainder, isThinkingPhase, isAgentStreaming }: {
 41→  segments: ContentSegment[];
 42→  streamingRemainder?: string;
 43→  isThinkingPhase: boolean;
 44→  isAgentStreaming: boolean;
 45→}) {
 46→  const { t } = useTranslation();
 47→  // All non-answer, non-chart, non-user_question segments go inside the thinking block
 48→  const thinkingSegments = segments.filter(
 49→    (s) => s.type !== 'answer' && s.type !== 'user_question' && !(s.type === 'tool' && s.toolResult?.chart_spec) && !(s.type === 'subagent_end' && (s.chart_spec || s.text?.trim()))
 50→  );
 51→  const hasContent = thinkingSegments.some(
 52→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult) || s.type === 'subagent_start'
 53→  ) || streamingRemainder?.trim();
 54→
 55→  if (!hasContent) return null;
 56→
 57→  // Show preview only while agent is still working (hidden by CSS when collapsible is open anyway)
 58→  const summary = isAgentStreaming ? getLastThinkingLine(segments, streamingRemainder, t) : '';
 59→
 60→  return (
 61→    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isThinkingPhase || undefined}>
 62→      <summary className="message-bubble__collapsible-summary">
 63→        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
 64→        {summary && <span className="message-bubble__collapsible-preview">{summary}</span>}
 65→      </summary>
 66→      <div className="message-bubble__thinking-body">
 67→        {thinkingSegments.map((seg, i) => {
 68→          if (seg.type === 'thinking' && seg.text?.trim()) {
 69→            return (
 70→              <div key={i} className="message-bubble__segment-content">
 71→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
 72→              </div>
 73→            );
 74→          }
 75→          if (seg.type === 'tool' && seg.toolResult) {
 76→            return (
 77→              <div key={i} className="message-bubble__tool-segment">
 78→                <InlineQueryResult result={seg.toolResult} />
 79→              </div>
 80→            );
 81→          }
 82→          if (seg.type === 'subagent_start') {
 83→            const displayName = seg.subagentName === 'sql-analyst'
 84→              ? t('sqlAnalystWorking')
 85→              : seg.subagentName === 'chart-builder'
 86→              ? t('chartBuilderWorking')
 87→              : `${seg.subagentName} working...`;
 88→            return (
 89→              <div key={i} className="message-bubble__subagent-indicator">
 90→                <span className="message-bubble__subagent-label">{displayName}</span>
 91→              </div>
 92→            );
 93→          }
 94→          return null;
 95→        })}
 96→        {streamingRemainder?.trim() && (
 97→          <div className="message-bubble__segment-content">
 98→            <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
 99→          </div>
100→        )}
101→      </div>
102→    </details>
103→  );
104→}
105→
106→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
107→  const { t } = useTranslation();
108→  const { isStreaming, editMessage, deleteMessage } = useAgent();
109→  const [isEditing, setIsEditing] = useState(false);
110→  const [editText, setEditText] = useState(message.content);
111→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
112→  const textareaRef = useRef<HTMLTextAreaElement>(null);
113→
114→  const isUser = message.role === 'user';
115→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
116→
117→  useEffect(() => {
118→    if (isEditing && textareaRef.current) {
119→      textareaRef.current.focus();
120→      textareaRef.current.selectionStart = textareaRef.current.value.length;
121→    }
122→  }, [isEditing]);
123→
124→  const handleEdit = () => {
125→    setEditText(message.content);
126→    setIsEditing(true);
127→    setIsConfirmingDelete(false);
128→  };
129→
130→  const handleCancelEdit = () => {
131→    setIsEditing(false);
132→    setEditText(message.content);
133→  };
134→
135→  const handleSaveEdit = () => {
136→    const trimmed = editText.trim();
137→    if (!trimmed || trimmed === message.content) {
138→      handleCancelEdit();
139→      return;
140→    }
141→    setIsEditing(false);
142→    editMessage(messageIndex, trimmed);
143→  };
144→
145→  const handleDeleteConfirm = () => {
146→    setIsConfirmingDelete(false);
147→    deleteMessage(messageIndex);
148→  };
149→
150→  const handleKeyDown = (e: React.KeyboardEvent) => {
151→    if (e.key === 'Escape') {
152→      handleCancelEdit();
153→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
154→      e.preventDefault();
155→      handleSaveEdit();
156→    }
157→  };
158→
159→  let streamingRemainder: string | undefined;
160→  if (hasSegments && message.isStreaming && message.content) {
161→    const segmentedText = message.segments!
162→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
163→      .map((s) => s.text || '')
164→      .join('');
165→    const remaining = message.content.slice(segmentedText.length);
166→    if (remaining.trim()) {
167→      streamingRemainder = remaining;
168→    }
169→  }
170→
171→  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
172→  const isInAnswerPhase = message.currentPhase === 'answer';
173→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
174→
175→  const hasCharts = hasSegments && message.segments!.some(
176→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
177→  );
178→
179→  const answerBlockSegments = hasSegments
180→    ? message.segments!
181→        .filter((s) =>
182→          (s.type === 'answer' && s.text?.trim()) ||
183→          (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim()) ||
184→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
185→          (s.type === 'subagent_end' && s.chart_spec)
186→        )
187→        .map((s) => {
188→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
189→            return { ...s, text: stripChartSpecBlocks(s.text) };
190→          }
191→          return s;
192→        })
193→        .filter((s) => {
194→          // Remove text segments that became empty after stripping chart blocks
195→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
196→            return false;
197→          }
198→          return true;
199→        })
200→    : [];
201→
202→  const questionSegments = hasSegments
203→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
204→    : [];
205→
206→  return (
207→    <div className={`message-bubble message-bubble--${message.role}`}>
208→      <div className="message-bubble__header">
209→        {isUser ? t('you') : t('assistant')}
210→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
211→          <span className="message-bubble__actions">
212→            <button
213→              className="message-bubble__action-btn"
214→              onClick={handleEdit}
215→              title={t('editMessage')}
216→            >
217→              &#9998;
218→            </button>
219→            <button
220→              className="message-bubble__action-btn message-bubble__action-btn--delete"
221→              onClick={() => setIsConfirmingDelete(true)}
222→              title={t('deleteMessage')}
223→            >
224→              &#128465;
225→            </button>
226→          </span>
227→        )}
228→      </div>
229→
230→      {isUser && isConfirmingDelete && (
231→        <div className="message-bubble__confirm-delete">
232→          <span>{t('deleteConfirm')}</span>
233→          <div className="message-bubble__confirm-actions">
234→            <button
235→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
236→              onClick={handleDeleteConfirm}
237→            >
238→              {t('delete')}
239→            </button>
240→            <button
241→              className="message-bubble__confirm-btn"
242→              onClick={() => setIsConfirmingDelete(false)}
243→            >
244→              {t('cancel')}
245→            </button>
246→          </div>
247→        </div>
248→      )}
249→
250→      {isUser && isEditing ? (
251→        <div className="message-bubble__edit-mode">
252→          <textarea
253→            ref={textareaRef}
254→            className="message-bubble__edit-textarea"
255→            value={editText}
256→            onChange={(e) => setEditText(e.target.value)}
257→            onKeyDown={handleKeyDown}
258→            rows={3}
259→          />
260→          <div className="message-bubble__edit-actions">
261→            <button
262→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
263→              onClick={handleSaveEdit}
264→            >
265→              {t('saveResend')}
266→            </button>
267→            <button
268→              className="message-bubble__edit-btn"
269→              onClick={handleCancelEdit}
270→            >
271→              {t('cancel')}
272→            </button>
273→          </div>
274→        </div>
275→      ) : hasSegments ? (
276→        <div className="message-bubble__segments">
277→          {!questionSegments.some((s) => !s.userAnswer) && (
278→            <ThinkingBlock
279→              segments={message.segments!}
280→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
281→              isThinkingPhase={isThinkingPhase}
282→              isAgentStreaming={!!message.isStreaming}
283→            />
284→          )}
285→          {questionSegments.map((seg, i) => (
286→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
287→              <UserQuestion
288→                questionData={seg.questionData!}
289→                userAnswer={seg.userAnswer}
290→                userFreeText={seg.userFreeText}
291→              />
292→            </div>
293→          ))}
294→          {answerBlockSegments.length > 0 && (
295→            <div className="message-bubble__segment message-bubble__segment--answer">
296→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
297→              {answerBlockSegments.map((seg, i) => {
298→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
299→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
300→                  return (
301→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
302→                      {seg.type === 'tool' && seg.toolResult ? (
303→                        <InlineQueryResult result={seg.toolResult!} />
304→                      ) : seg.chart_spec ? (
305→                        <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
306→                      ) : null}
307→                    </div>
308→                  );
309→                }
310→                // Text segment (answer or subagent_end without chart_spec)
311→                return (
312→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
313→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
314→                  </div>
315→                );
316→              })}
317→            </div>
318→          )}
319→          {isInAnswerPhase && streamingRemainder?.trim() && (() => {
320→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
321→            return displayText?.trim() ? (
322→              <div className="message-bubble__segment message-bubble__segment--answer">
323→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
324→                <div className="message-bubble__segment-content">
325→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
326→                </div>
327→              </div>
328→            ) : null;
329→          })()}
330→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
331→            <span className="message-bubble__typing">{t('thinking')}</span>
332→          )}
333→        </div>
334→      ) : (
335→        <>
336→          <div className="message-bubble__content">
337→            {message.content ? (
338→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
339→            ) : message.isStreaming ? (
340→              <span className="message-bubble__typing">{t('thinking')}</span>
341→            ) : null}
342→          </div>
343→          {message.toolCalls && message.toolCalls.length > 0 && (
344→            <div className="message-bubble__tools">
345→              {message.toolCalls.map((tc) => (
346→                <InlineQueryResult key={tc.toolCallId} result={tc} />
347→              ))}
348→            </div>
349→          )}
350→        </>
351→      )}
352→    </div>
353→  );
354→}
