  1→import {
  2→  useCallback,
  3→  useRef,
  4→  useState,
  5→  type ReactNode,
  6→} from 'react';
  7→import { AgentContext } from '../hooks/useAgent';
  8→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
  9→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 10→import { useSessionId } from '../hooks/useSessionId';
 11→import { generateUUID } from '../utils/uuid';
 12→
 13→function generateId() {
 14→  return generateUUID();
 15→}
 16→
 17→export function AgentProvider({
 18→  children,
 19→  refreshTables,
 20→}: {
 21→  children: ReactNode;
 22→  refreshTables: () => Promise<void>;
 23→}) {
 24→  const userSessionId = useSessionId();
 25→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 26→  const [isStreaming, setIsStreaming] = useState(false);
 27→  const abortRef = useRef<AbortController | null>(null);
 28→  const textBufferRef = useRef('');
 29→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 30→  const assistantIdRef = useRef('');
 31→  const segmentsRef = useRef<ContentSegment[]>([]);
 32→  const currentTextRef = useRef('');
 33→  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
 34→  const sessionIdRef = useRef<string | null>(null);
 35→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 36→
 37→  const flushText = useCallback(() => {
 38→    const text = textBufferRef.current;
 39→    if (!text) return;
 40→    const id = assistantIdRef.current;
 41→    currentTextRef.current += text;
 42→    setMessages((prev) =>
 43→      prev.map((m) =>
 44→        m.id === id ? { ...m, content: m.content + text } : m
 45→      )
 46→    );
 47→    textBufferRef.current = '';
 48→  }, []);
 49→
 50→  const sendMessage = useCallback(
 51→    async (text: string) => {
 52→      if (isStreaming) return;
 53→
 54→      const userMsg: ChatMessage = {
 55→        id: generateId(),
 56→        role: 'user',
 57→        content: text,
 58→      };
 59→
 60→      const assistantId = generateId();
 61→      assistantIdRef.current = assistantId;
 62→      const assistantMsg: ChatMessage = {
 63→        id: assistantId,
 64→        role: 'assistant',
 65→        content: '',
 66→        toolCalls: [],
 67→        isStreaming: true,
 68→      };
 69→
 70→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 71→      setIsStreaming(true);
 72→      textBufferRef.current = '';
 73→      segmentsRef.current = [];
 74→      currentTextRef.current = '';
 75→      phaseRef.current = 'thinking';
 76→
 77→      // If there's pending history from a delete, start a new Langfuse session with that context
 78→      const pendingHistory = pendingHistoryRef.current;
 79→      pendingHistoryRef.current = null;
 80→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
 81→
 82→      const controller = new AbortController();
 83→      abortRef.current = controller;
 84→
 85→      await runAgentLoop(
 86→        text,
 87→        sessionIdRef.current,
 88→        langfuseSessionId,
 89→        pendingHistory,
 90→        {
 91→          onTextChunk: (chunk) => {
 92→            textBufferRef.current += chunk;
 93→            if (!flushTimerRef.current) {
 94→              flushTimerRef.current = setTimeout(() => {
 95→                flushText();
 96→                flushTimerRef.current = null;
 97→              }, 50);
 98→            }
 99→          },
100→          onThinkingDone: () => {
101→            // Extended thinking just ended and a text block is starting.
102→            // Create a thinking segment from accumulated thinking text.
103→            if (flushTimerRef.current) {
104→              clearTimeout(flushTimerRef.current);
105→              flushTimerRef.current = null;
106→            }
107→            flushText();
108→            if (currentTextRef.current.trim()) {
109→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
110→              currentTextRef.current = '';
111→            }
112→            phaseRef.current = 'answer';
113→            setMessages((prev) =>
114→              prev.map((m) =>
115→                m.id === assistantId
116→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
117→                  : m
118→              )
119→            );
120→          },
121→          onToolCall: (pending: ToolCallResult) => {
122→            if (flushTimerRef.current) {
123→              clearTimeout(flushTimerRef.current);
124→              flushTimerRef.current = null;
125→            }
126→            flushText();
127→            if (currentTextRef.current.trim()) {
128→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
129→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
130→              currentTextRef.current = '';
131→            }
132→            // Add a pending tool segment so the input is shown immediately
133→            segmentsRef.current.push({
134→              type: 'tool',
135→              toolResult: pending,
136→            });
137→            setMessages((prev) =>
138→              prev.map((m) =>
139→                m.id === assistantId
140→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
141→                  : m
142→              )
143→            );
144→          },
145→          onToolResult: (result: ToolCallResult) => {
146→            // Merge result into pending tool segment (keep input info, add output)
147→            const pendingIdx = segmentsRef.current.findIndex(
148→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
149→            );
150→            if (pendingIdx !== -1) {
151→              const pending = segmentsRef.current[pendingIdx].toolResult!;
152→              segmentsRef.current[pendingIdx] = {
153→                type: 'tool',
154→                toolResult: {
155→                  ...pending,
156→                  ...result,
157→                  sql: result.sql || pending.sql,
158→                  toolName: result.toolName || pending.toolName,
159→                  command: result.command || pending.command,
160→                  toolInput: result.toolInput || pending.toolInput,
161→                },
162→              };
163→            } else {
164→              segmentsRef.current.push({ type: 'tool', toolResult: result });
165→            }
166→            setMessages((prev) =>
167→              prev.map((m) =>
168→                m.id === assistantId
169→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
170→                  : m
171→              )
172→            );
173→            refreshTables();
174→          },
175→          onSubagentStart: (data) => {
176→            if (flushTimerRef.current) {
177→              clearTimeout(flushTimerRef.current);
178→              flushTimerRef.current = null;
179→            }
180→            flushText();
181→            if (currentTextRef.current.trim()) {
182→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
183→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
184→              currentTextRef.current = '';
185→            }
186→            segmentsRef.current.push({
187→              type: 'subagent_start',
188→              subagentId: data.id,
189→              subagentName: data.name,
190→              text: data.prompt,
191→            });
192→            setMessages((prev) =>
193→              prev.map((m) =>
194→                m.id === assistantId
195→                  ? { ...m, segments: [...segmentsRef.current] }
196→                  : m
197→              )
198→            );
199→          },
200→          onSubagentEnd: (data) => {
201→            segmentsRef.current.push({
202→              type: 'subagent_end',
203→              subagentId: data.id,
204→              subagentName: data.name,
205→              chart_spec: data.chart_spec,
206→              text: data.result,
207→            });
208→            setMessages((prev) =>
209→              prev.map((m) =>
210→                m.id === assistantId
211→                  ? { ...m, segments: [...segmentsRef.current] }
212→                  : m
213→              )
214→            );
215→          },
216→          onDone: (newSessionId) => {
217→            if (newSessionId) sessionIdRef.current = newSessionId;
218→            if (flushTimerRef.current) {
219→              clearTimeout(flushTimerRef.current);
220→              flushTimerRef.current = null;
221→            }
222→            flushText();
223→            if (currentTextRef.current.trim()) {
224→              segmentsRef.current.push({
225→                type: 'answer',
226→                text: currentTextRef.current,
227→              });
228→              currentTextRef.current = '';
229→            }
230→            setMessages((prev) =>
231→              prev.map((m) =>
232→                m.id === assistantId
233→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
234→                  : m
235→              )
236→            );
237→            setIsStreaming(false);
238→            abortRef.current = null;
239→          },
240→          onError: (error) => {
241→            if (flushTimerRef.current) {
242→              clearTimeout(flushTimerRef.current);
243→              flushTimerRef.current = null;
244→            }
245→            flushText();
246→            setMessages((prev) =>
247→              prev.map((m) =>
248→                m.id === assistantId
249→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
250→                  : m
251→              )
252→            );
253→            setIsStreaming(false);
254→            abortRef.current = null;
255→          },
256→          onUserQuestion: (data) => {
257→            if (flushTimerRef.current) {
258→              clearTimeout(flushTimerRef.current);
259→              flushTimerRef.current = null;
260→            }
261→            flushText();
262→            if (currentTextRef.current.trim()) {
263→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
264→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
265→              currentTextRef.current = '';
266→            }
267→            segmentsRef.current.push({
268→              type: 'user_question',
269→              questionData: data,
270→            });
271→            setMessages((prev) =>
272→              prev.map((m) =>
273→                m.id === assistantId
274→                  ? { ...m, segments: [...segmentsRef.current] }
275→                  : m
276→              )
277→            );
278→          },
279→        },
280→        controller.signal,
281→        userSessionId,
282→      );
283→    },
284→    [isStreaming, flushText, refreshTables, userSessionId]
285→  );
286→
287→  const editMessage = useCallback(
288→    async (messageIndex: number, newContent: string) => {
289→      if (isStreaming) return;
290→
291→      // Build conversation history from messages before the edit point
292→      const conversationHistory: { role: string; content: string }[] = [];
293→      for (let i = 0; i < messageIndex; i++) {
294→        const msg = messages[i];
295→        if (msg.role === 'user' || msg.role === 'assistant') {
296→          conversationHistory.push({ role: msg.role, content: msg.content });
297→        }
298→      }
299→
300→      const assistantId = generateId();
301→      assistantIdRef.current = assistantId;
302→
303→      const userMsg: ChatMessage = {
304→        id: generateId(),
305→        role: 'user',
306→        content: newContent,
307→      };
308→      const assistantMsg: ChatMessage = {
309→        id: assistantId,
310→        role: 'assistant',
311→        content: '',
312→        toolCalls: [],
313→        isStreaming: true,
314→      };
315→
316→      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
317→      setIsStreaming(true);
318→      textBufferRef.current = '';
319→      segmentsRef.current = [];
320→      currentTextRef.current = '';
321→      phaseRef.current = 'thinking';
322→
323→      const controller = new AbortController();
324→      abortRef.current = controller;
325→
326→      await runAgentEditLoop(
327→        newContent,
328→        conversationHistory,
329→        generateUUID(),
330→        {
331→          onTextChunk: (chunk) => {
332→            textBufferRef.current += chunk;
333→            if (!flushTimerRef.current) {
334→              flushTimerRef.current = setTimeout(() => {
335→                flushText();
336→                flushTimerRef.current = null;
337→              }, 50);
338→            }
339→          },
340→          onThinkingDone: () => {
341→            if (flushTimerRef.current) {
342→              clearTimeout(flushTimerRef.current);
343→              flushTimerRef.current = null;
344→            }
345→            flushText();
346→            if (currentTextRef.current.trim()) {
347→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
348→              currentTextRef.current = '';
349→            }
350→            phaseRef.current = 'answer';
351→            setMessages((prev) =>
352→              prev.map((m) =>
353→                m.id === assistantId
354→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
355→                  : m
356→              )
357→            );
358→          },
359→          onToolCall: (pending: ToolCallResult) => {
360→            if (flushTimerRef.current) {
361→              clearTimeout(flushTimerRef.current);
362→              flushTimerRef.current = null;
363→            }
364→            flushText();
365→            if (currentTextRef.current.trim()) {
366→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
367→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
368→              currentTextRef.current = '';
369→            }
370→            segmentsRef.current.push({ type: 'tool', toolResult: pending });
371→            setMessages((prev) =>
372→              prev.map((m) =>
373→                m.id === assistantId
374→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
375→                  : m
376→              )
377→            );
378→          },
379→          onToolResult: (result: ToolCallResult) => {
380→            const pendingIdx = segmentsRef.current.findIndex(
381→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
382→            );
383→            if (pendingIdx !== -1) {
384→              const pending = segmentsRef.current[pendingIdx].toolResult!;
385→              segmentsRef.current[pendingIdx] = {
386→                type: 'tool',
387→                toolResult: {
388→                  ...pending,
389→                  ...result,
390→                  sql: result.sql || pending.sql,
391→                  toolName: result.toolName || pending.toolName,
392→                  command: result.command || pending.command,
393→                  toolInput: result.toolInput || pending.toolInput,
394→                },
395→              };
396→            } else {
397→              segmentsRef.current.push({ type: 'tool', toolResult: result });
398→            }
399→            setMessages((prev) =>
400→              prev.map((m) =>
401→                m.id === assistantId
402→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
403→                  : m
404→              )
405→            );
406→            refreshTables();
407→          },
408→          onSubagentStart: (data) => {
409→            if (flushTimerRef.current) {
410→              clearTimeout(flushTimerRef.current);
411→              flushTimerRef.current = null;
412→            }
413→            flushText();
414→            if (currentTextRef.current.trim()) {
415→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
416→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
417→              currentTextRef.current = '';
418→            }
419→            segmentsRef.current.push({
420→              type: 'subagent_start',
421→              subagentId: data.id,
422→              subagentName: data.name,
423→              text: data.prompt,
424→            });
425→            setMessages((prev) =>
426→              prev.map((m) =>
427→                m.id === assistantId
428→                  ? { ...m, segments: [...segmentsRef.current] }
429→                  : m
430→              )
431→            );
432→          },
433→          onSubagentEnd: (data) => {
434→            segmentsRef.current.push({
435→              type: 'subagent_end',
436→              subagentId: data.id,
437→              subagentName: data.name,
438→              chart_spec: data.chart_spec,
439→              text: data.result,
440→            });
441→            setMessages((prev) =>
442→              prev.map((m) =>
443→                m.id === assistantId
444→                  ? { ...m, segments: [...segmentsRef.current] }
445→                  : m
446→              )
447→            );
448→          },
449→          onDone: (newSessionId) => {
450→            if (newSessionId) sessionIdRef.current = newSessionId;
451→            if (flushTimerRef.current) {
452→              clearTimeout(flushTimerRef.current);
453→              flushTimerRef.current = null;
454→            }
455→            flushText();
456→            if (currentTextRef.current.trim()) {
457→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
458→              currentTextRef.current = '';
459→            }
460→            setMessages((prev) =>
461→              prev.map((m) =>
462→                m.id === assistantId
463→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
464→                  : m
465→              )
466→            );
467→            setIsStreaming(false);
468→            abortRef.current = null;
469→          },
470→          onError: (error) => {
471→            if (flushTimerRef.current) {
472→              clearTimeout(flushTimerRef.current);
473→              flushTimerRef.current = null;
474→            }
475→            flushText();
476→            setMessages((prev) =>
477→              prev.map((m) =>
478→                m.id === assistantId
479→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
480→                  : m
481→              )
482→            );
483→            setIsStreaming(false);
484→            abortRef.current = null;
485→          },
486→          onUserQuestion: (data) => {
487→            if (flushTimerRef.current) {
488→              clearTimeout(flushTimerRef.current);
489→              flushTimerRef.current = null;
490→            }
491→            flushText();
492→            if (currentTextRef.current.trim()) {
493→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
494→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
495→              currentTextRef.current = '';
496→            }
497→            segmentsRef.current.push({
498→              type: 'user_question',
499→              questionData: data,
500→            });
501→            setMessages((prev) =>
502→              prev.map((m) =>
503→                m.id === assistantId
504→                  ? { ...m, segments: [...segmentsRef.current] }
505→                  : m
506→              )
507→            );
508→          },
509→        },
510→        controller.signal,
511→        userSessionId,
512→      );
513→    },
514→    [isStreaming, messages, flushText, refreshTables, userSessionId]
515→  );
516→
517→  const deleteMessage = useCallback(
518→    (messageIndex: number) => {
519→      if (isStreaming) return;
520→
521→      // Store remaining messages as history for Langfuse context on next send
522→      setMessages((prev) => {
523→        const remaining = prev.slice(0, messageIndex);
524→        pendingHistoryRef.current = remaining
525→          .filter((m) => m.role === 'user' || m.role === 'assistant')
526→          .map((m) => ({ role: m.role, content: m.content }));
527→        return remaining;
528→      });
529→
530→      // Clear session so next message starts fresh
531→      sessionIdRef.current = null;
532→    },
533→    [isStreaming]
534→  );
535→
536→  const respondToQuestion = useCallback(
537→    async (questionId: string, answers: string[], freeText?: string) => {
538→      // Update the segment to show the user's answer
539→      const segIdx = segmentsRef.current.findIndex(
540→        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
541→      );
542→      if (segIdx !== -1) {
543→        segmentsRef.current[segIdx] = {
544→          ...segmentsRef.current[segIdx],
545→          userAnswer: answers,
546→          userFreeText: freeText,
547→        };
548→        setMessages((prev) =>
549→          prev.map((m) =>
550→            m.id === assistantIdRef.current
551→              ? { ...m, segments: [...segmentsRef.current] }
552→              : m
553→          )
554→        );
555→      }
556→
557→      // POST to backend
558→      try {
559→        await fetch('/api/chat/respond', {
560→          method: 'POST',
561→          headers: {
562→            'Content-Type': 'application/json',
563→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
564→          },
565→          body: JSON.stringify({
566→            question_id: questionId,
567→            answers,
568→            free_text: freeText || null,
569→          }),
570→        });
571→      } catch (e) {
572→        console.error('Failed to respond to question:', e);
573→      }
574→    },
575→    [userSessionId]
576→  );
577→
578→  const clearMessages = useCallback(() => {
579→    if (abortRef.current) {
580→      abortRef.current.abort();
581→    }
582→    setMessages([]);
583→    setIsStreaming(false);
584→    sessionIdRef.current = null;
585→    pendingHistoryRef.current = null;
586→  }, []);
587→
588→  return (
589→    <AgentContext.Provider
590→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, respondToQuestion }}
591→    >
592→      {children}
593→    </AgentContext.Provider>
594→  );
595→}
